const raw = $json;

const message =
  Array.isArray(raw.messages)
    ? raw.messages[0]
    : null;

const contact =
  Array.isArray(raw.contacts)
    ? raw.contacts[0]
    : null;


// ======================================================
// VALIDAR EVENTO
// ======================================================

if (!message) {
  return {
    json: {
      event_type: 'UNSUPPORTED_EVENT',
      raw_payload: raw
    }
  };
}


// ======================================================
// TIMESTAMP
// ======================================================

let providerTimestamp = null;

if (message.timestamp) {

  const unix =
    Number(message.timestamp);

  if (
    Number.isFinite(unix)
    && unix > 0
  ) {
    providerTimestamp =
      new Date(unix * 1000).toISOString();
  }
}

providerTimestamp =
  providerTimestamp
  ?? new Date().toISOString();


// ======================================================
// IDENTIDADE DO CLIENTE
// ======================================================

const externalUserId =
  contact?.wa_id
  ?? message.from
  ?? null;

const profileName =
  contact?.profile?.name
  ?? null;


// ======================================================
// CONTEÚDO
// ======================================================

const originalType =
  String(
    message.type
    ?? 'unknown'
  ).toLowerCase();

let text = null;

let interaction = null;

let media = {
  id: null,
  mime_type: null,
  url: null,
  caption: null,
  filename: null
};


// ======================================================
// TEXTO
// ======================================================

if (originalType === 'text') {

  text =
    message.text?.body
    ?? null;
}


// ======================================================
// INTERACTIVE
// ======================================================

if (originalType === 'interactive') {

  const interactiveType =
    message.interactive?.type
    ?? null;


  // ----------------------------------------------------
  // LIST REPLY
  // ----------------------------------------------------

  if (interactiveType === 'list_reply') {

    const reply =
      message.interactive?.list_reply
      ?? {};

    const replyId =
      reply.id
      ?? null;

    let slotOfferId = null;
    let optionNumber = null;


    if (
      typeof replyId === 'string'
      && replyId.startsWith('slot|')
    ) {

      const parts =
        replyId.split('|');

      if (
        parts.length === 3
        && parts[0] === 'slot'
      ) {

        slotOfferId =
          parts[1]
          ?? null;

        const parsedOption =
          Number(parts[2]);

        if (
          Number.isInteger(parsedOption)
          && parsedOption >= 1
        ) {
          optionNumber =
            parsedOption;
        }
      }
    }


    interaction = {

      kind:
        'LIST_REPLY',

      action:
        slotOfferId && optionNumber
          ? 'SELECT_SLOT'
          : null,

      reply_id:
        replyId,

      title:
        reply.title
        ?? null,

      description:
        reply.description
        ?? null,

      slot_offer_id:
        slotOfferId,

      option_number:
        optionNumber
    };


    // Texto humano também fica disponível para histórico/IA.
    text =
      reply.title
      ?? null;
  }


  // ----------------------------------------------------
  // BUTTON REPLY
  // ----------------------------------------------------

  else if (interactiveType === 'button_reply') {

    const reply =
      message.interactive?.button_reply
      ?? {};

    const replyId =
      reply.id
      ?? null;

    let slotOfferId = null;
    let optionNumber = null;


    if (
      typeof replyId === 'string'
      && replyId.startsWith('slot|')
    ) {

      const parts =
        replyId.split('|');

      if (
        parts.length === 3
        && parts[0] === 'slot'
      ) {

        slotOfferId =
          parts[1]
          ?? null;

        const parsedOption =
          Number(parts[2]);

        if (
          Number.isInteger(parsedOption)
          && parsedOption >= 1
        ) {
          optionNumber =
            parsedOption;
        }
      }
    }


    interaction = {

      kind:
        'BUTTON_REPLY',

      action:
        slotOfferId && optionNumber
          ? 'SELECT_SLOT'
          : null,

      reply_id:
        replyId,

      title:
        reply.title
        ?? null,

      slot_offer_id:
        slotOfferId,

      option_number:
        optionNumber
    };


    text =
      reply.title
      ?? null;
  }
}


// ======================================================
// ÁUDIO
// ======================================================

if (originalType === 'audio') {

  media = {
    ...media,

    id:
      message.audio?.id
      ?? null,

    mime_type:
      message.audio?.mime_type
      ?? null
  };
}


// ======================================================
// IMAGEM
// ======================================================

if (originalType === 'image') {

  media = {
    ...media,

    id:
      message.image?.id
      ?? null,

    mime_type:
      message.image?.mime_type
      ?? null,

    caption:
      message.image?.caption
      ?? null
  };

  text =
    message.image?.caption
    ?? null;
}


// ======================================================
// DOCUMENTO
// ======================================================

if (originalType === 'document') {

  media = {
    ...media,

    id:
      message.document?.id
      ?? null,

    mime_type:
      message.document?.mime_type
      ?? null,

    caption:
      message.document?.caption
      ?? null,

    filename:
      message.document?.filename
      ?? null
  };

  text =
    message.document?.caption
    ?? null;
}


// ======================================================
// VÍDEO
// ======================================================

if (originalType === 'video') {

  media = {
    ...media,

    id:
      message.video?.id
      ?? null,

    mime_type:
      message.video?.mime_type
      ?? null,

    caption:
      message.video?.caption
      ?? null
  };

  text =
    message.video?.caption
    ?? null;
}


// ======================================================
// OUTPUT CANÔNICO
// ======================================================

return {
  json: {

    event_type:
      'INBOUND_MESSAGE',

    dev:
      false,

    /*
     * TEMPORÁRIO DURANTE O TESTE DA BARBEARIA.
     *
     * Depois vamos resolver a empresa pelo phone_number_id
     * cadastrado em business_channels, sem hardcode.
     */
    business_code:
      'BARB001',

    channel: {

      type:
        'WHATSAPP',

      provider:
        'META',

      external_channel_id:
        raw.metadata?.phone_number_id
        ?? null
    },

    customer: {

      external_user_id:
        externalUserId,

      profile_name:
        profileName
    },

    message: {

      external_message_id:
        message.id
        ?? null,

      idempotency_key:
        message.id
          ? `IN:META:${message.id}`
          : null,

      type:
        originalType,

      text,

      interaction,

      media,

      reply_to_external_message_id:
        message.context?.id
        ?? null,

      provider_timestamp:
        providerTimestamp,

      raw_payload:
        raw
    },

    received_at:
      new Date().toISOString()
  }
};

const input =
  $('01 - NORMALIZAR ENTRADA').first().json;

const context =
  $('02 - CARREGAR CONTEXTO CORE').first().json.context ?? {};

const interaction =
  input.message?.interaction ?? null;


// ======================================================
// HELPERS
// ======================================================

const emptyArguments = () => ({
  service_id: null,
  professional_id: null,
  date: null,
  period: null,
  time: null,
  time_from: null,
  time_until: null,
  option_number: null,
  appointment_id: null,
  allow_professional_fallback: false
});


const UUID_REGEX =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;


// ======================================================
// HELPER - REBOOK A PARTIR DO CONTEXTO
// ======================================================
//
// Usado quando uma lista de horários expirou durante
// um fluxo de reagendamento iniciado por cancelamento.
//
// NÃO confiamos em serviço, profissional ou horário
// armazenados no contexto.
//
// A única referência operacional é appointment_id.
//
// O CORE continuará responsável por validar:
// - empresa
// - cliente
// - ownership
// - status CANCELLED
// - ator do cancelamento
// - profissional
// - serviços
// - disponibilidade
// ======================================================

const buildRebookFromContext = () => {

  const rebooking =
    context.conversation?.context?.rebooking
    ?? null;

  const appointmentId =
    rebooking?.source_appointment_id
    ?? null;


  if (
    !appointmentId
    || typeof appointmentId !== 'string'
    || !UUID_REGEX.test(appointmentId)
  ) {
    return null;
  }


  return {
    json: {
      structured_command: {

        kind:
          'BUSINESS_ACTION',

        intent:
          'REBOOK_APPOINTMENT',

        action:
          'REBOOK_APPOINTMENT',

        arguments: {
          ...emptyArguments(),

          appointment_id:
            appointmentId
        },

        missing_information:
          [],

        customer_meaning:
          'A lista anterior de horários expirou durante o reagendamento. O cliente continua querendo outro horário para o agendamento cancelado.',

        direct_response:
          null,

        confidence:
          1
      }
    }
  };
};


// ======================================================
// VALIDAR EXISTÊNCIA DA INTERAÇÃO
// ======================================================

if (!interaction) {
  return {
    json: {
      structured_command: {

        kind:
          'NEED_INFORMATION',

        intent:
          'OTHER',

        action:
          'NONE',

        arguments:
          emptyArguments(),

        missing_information: [
          'CLARIFICATION'
        ],

        customer_meaning:
          'Interação estruturada não reconhecida.',

        direct_response:
          'Não consegui identificar essa opção. Pode tentar novamente?',

        confidence:
          1
      }
    }
  };
}


// ======================================================
// IDENTIFICAR TIPO DE AÇÃO ESTRUTURADA
// ======================================================

const replyId =
  typeof interaction.reply_id === 'string'
    ? interaction.reply_id.trim()
    : '';

const isSelectSlot =
  interaction.action === 'SELECT_SLOT';

const isRebook =
  replyId.startsWith('rebook|');


// ======================================================
// REBOOK DE AGENDAMENTO CANCELADO
// ======================================================

if (isRebook) {

  const parts =
    replyId.split('|');

  const appointmentId =
    parts.length === 2
      ? parts[1]
      : null;


  // ----------------------------------------------------
  // VALIDAR FORMATO
  // ----------------------------------------------------

  if (
    !appointmentId
    || !UUID_REGEX.test(appointmentId)
  ) {
    return {
      json: {
        structured_command: {

          kind:
            'NEED_INFORMATION',

          intent:
            'REBOOK_APPOINTMENT',

          action:
            'NONE',

          arguments:
            emptyArguments(),

          missing_information: [
            'APPOINTMENT_REFERENCE'
          ],

          customer_meaning:
            'Cliente clicou em um botão de reagendamento inválido.',

          direct_response:
            'Não consegui identificar o agendamento que você quer remarcar. Posso te ajudar a procurar outro horário.',

          confidence:
            1
        }
      }
    };
  }


  // ----------------------------------------------------
  // NÃO CONFIAR NO CONTEXTO ANTIGO DE BOOKING.
  //
  // O appointment_id é a referência determinística.
  //
  // O CORE validará:
  // - empresa
  // - cliente
  // - status
  // - cancelamento
  // - profissional
  // - serviços
  // ----------------------------------------------------

  return {
    json: {
      structured_command: {

        kind:
          'BUSINESS_ACTION',

        intent:
          'REBOOK_APPOINTMENT',

        action:
          'REBOOK_APPOINTMENT',

        arguments: {
          ...emptyArguments(),

          appointment_id:
            appointmentId
        },

        missing_information:
          [],

        customer_meaning:
          'Cliente quer procurar um novo horário a partir do agendamento cancelado.',

        direct_response:
          null,

        confidence:
          1
      }
    }
  };
}


// ======================================================
// SELECT_SLOT
// ======================================================

if (isSelectSlot) {

  const activeOffer =
    context.active_offer
    ?? null;

  const clickedOfferId =
    typeof interaction.slot_offer_id === 'string'
      ? interaction.slot_offer_id.trim()
      : null;

  const optionNumber =
    interaction.option_number
    ?? null;


  // ====================================================
  // VALIDAR IDENTIFICADOR DA OFERTA CLICADA
  // ====================================================

  if (
    !clickedOfferId
    || !UUID_REGEX.test(clickedOfferId)
  ) {
    return {
      json: {
        structured_command: {

          kind:
            'NEED_INFORMATION',

          intent:
            'SELECT_SLOT',

          action:
            'NONE',

          arguments:
            emptyArguments(),

          missing_information: [
            'SLOT_OFFER'
          ],

          customer_meaning:
            'Cliente clicou em uma opção cujo identificador da oferta é inválido.',

          direct_response:
            'Não consegui identificar essa lista de horários. Posso buscar opções atualizadas pra você.',

          confidence:
            1
        }
      }
    };
  }


  // ====================================================
  // NÃO EXISTE MAIS OFERTA ATIVA
  //
  // A lista expirou.
  //
  // Se estivermos dentro de um fluxo de rebooking,
  // regeneramos a oferta automaticamente.
  // ====================================================

  if (!activeOffer) {

    const automaticRebook =
      buildRebookFromContext();


    if (automaticRebook) {
      return automaticRebook;
    }


    // --------------------------------------------------
    // Não existe contexto suficiente para regenerar
    // deterministicamente.
    // --------------------------------------------------

    return {
      json: {
        structured_command: {

          kind:
            'CONVERSATION',

          intent:
            'SELECT_SLOT',

          action:
            'NONE',

          arguments:
            emptyArguments(),

          missing_information:
            [],

          customer_meaning:
            'Cliente selecionou uma opção de uma oferta que expirou e não há contexto suficiente para regenerá-la automaticamente.',

          direct_response:
            'Essa lista já não está mais ativa. Me diga o dia ou horário que você procura e eu verifico novamente.',

          confidence:
            1
        }
      }
    };
  }


  // ====================================================
  // EXISTE OFERTA ATIVA, MAS O CLIENTE CLICOU EM OUTRA
  //
  // Isso pode ocorrer quando:
  // - existe uma lista antiga na conversa;
  // - uma nova oferta já foi criada depois;
  // - o cliente clicou na mensagem antiga.
  //
  // NÃO criamos outra oferta aqui para evitar:
  // - múltiplas ofertas concorrentes;
  // - invalidar uma oferta recém-criada;
  // - loops de regeneração.
  // ====================================================

  if (
    activeOffer.slot_offer_id !== clickedOfferId
  ) {
    return {
      json: {
        structured_command: {

          kind:
            'CONVERSATION',

          intent:
            'SELECT_SLOT',

          action:
            'NONE',

          arguments:
            emptyArguments(),

          missing_information:
            [],

          customer_meaning:
            'Cliente clicou em uma lista antiga enquanto já existe uma oferta de horários mais recente ativa.',

          direct_response:
            'Essa lista é antiga. Use a lista de horários mais recente que enviei pra você.',

          confidence:
            1
        }
      }
    };
  }


  // ====================================================
  // VALIDAR OPTION_NUMBER
  // ====================================================

  if (
    !Number.isInteger(optionNumber)
    || optionNumber <= 0
  ) {
    return {
      json: {
        structured_command: {

          kind:
            'NEED_INFORMATION',

          intent:
            'SELECT_SLOT',

          action:
            'NONE',

          arguments:
            emptyArguments(),

          missing_information: [
            'SLOT_OPTION'
          ],

          customer_meaning:
            'Cliente clicou em uma opção com número inválido.',

          direct_response:
            'Não consegui identificar esse horário. Pode escolher uma opção da lista novamente.',

          confidence:
            1
        }
      }
    };
  }


  // ====================================================
  // VALIDAR OPÇÃO
  // ====================================================

  const selectedOption =
    Array.isArray(activeOffer.options)
      ? activeOffer.options.find(
          option =>
            option.option_number === optionNumber
        )
      : null;


  if (!selectedOption) {
    return {
      json: {
        structured_command: {

          kind:
            'NEED_INFORMATION',

          intent:
            'SELECT_SLOT',

          action:
            'NONE',

          arguments:
            emptyArguments(),

          missing_information: [
            'SLOT_OPTION'
          ],

          customer_meaning:
            'Cliente clicou em uma opção que não existe na oferta ativa.',

          direct_response:
            'Essa opção não está mais disponível. Pode escolher outro horário da lista.',

          confidence:
            1
        }
      }
    };
  }


  // ====================================================
  // COMANDO DETERMINÍSTICO SELECT_SLOT
  // ====================================================

  return {
    json: {
      structured_command: {

        kind:
          'BUSINESS_ACTION',

        intent:
          'SELECT_SLOT',

        action:
          'SELECT_SLOT',

        arguments: {

          service_id:
            null,

          professional_id:
            selectedOption.professional_id
            ?? null,

          date:
            selectedOption.local_date
            ?? null,

          period:
            null,

          time:
            selectedOption.local_start
            ?? interaction.title
            ?? null,

          time_from:
            null,

          time_until:
            null,

          option_number:
            optionNumber,

          appointment_id:
            null,

          allow_professional_fallback:
            false,

          slot_offer_id:
            clickedOfferId
        },

        missing_information:
          [],

        customer_meaning:
          `Cliente selecionou o horário ${selectedOption.local_start ?? interaction.title ?? ''}.`,

        direct_response:
          null,

        confidence:
          1
      }
    }
  };
}


// ======================================================
// INTERAÇÃO ESTRUTURADA DESCONHECIDA
// ======================================================

return {
  json: {
    structured_command: {

      kind:
        'NEED_INFORMATION',

      intent:
        'OTHER',

      action:
        'NONE',

      arguments:
        emptyArguments(),

      missing_information: [
        'CLARIFICATION'
      ],

      customer_meaning:
        'Interação estruturada não reconhecida.',

      direct_response:
        'Não consegui identificar essa opção. Pode tentar novamente?',

      confidence:
        1
    }
  }
};

return {
  json: {
    structured_command: {
      kind: 'CONVERSATION',
      intent: 'OTHER',
      action: 'NONE',
      arguments: {
        service_id: null,
        professional_id: null,
        date: null,
        period: null,
        time: null,
        time_from: null,
        time_until: null,
        option_number: null,
        appointment_id: null,
        allow_professional_fallback: false
      },
      missing_information: [],
      customer_meaning: 'Falha temporária da camada de interpretação; nenhuma ação operacional deve ser executada.',
      direct_response: 'Tive um problema para interpretar sua mensagem agora. Pode me mandar de novo em uma frase curta?',
      confidence: 1
    }
  }
};

const envelope = $json;

const context =
  $('02 - CARREGAR CONTEXTO CORE').item.json.context ?? {};


// ======================================================
// EXTRAIR COMANDO DA IA / COMANDO ESTRUTURADO
// ======================================================

let command =
  envelope.structured_command
  ?? envelope.output?.[0]?.content
      ?.find(item => item.type === 'output_text')
      ?.text
  ?? null;

if (typeof command === 'string') {
  try {
    command = JSON.parse(command);
  } catch {
    command = null;
  }
}


// ======================================================
// ESTRUTURAS DE VALIDAÇÃO
// ======================================================

const errors = [];
const warnings = [];

if (!command || typeof command !== 'object') {
  errors.push('INVALID_AI_OUTPUT');
}


// ======================================================
// HELPERS
// ======================================================

const uuidRegex =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;


// ======================================================
// TIPOS E AÇÕES PERMITIDOS
// ======================================================

const allowedKinds = new Set([
  'BUSINESS_ACTION',
  'CONVERSATION',
  'NEED_INFORMATION',
  'HUMAN_HANDOFF'
]);

const allowedActions = new Set([
  'SEARCH_AVAILABILITY',
  'SELECT_SLOT',
  'CANCEL_APPOINTMENT',
  'RESCHEDULE_APPOINTMENT',
  'REBOOK_APPOINTMENT',
  'GET_APPOINTMENT',
  'JOIN_WAITLIST',
  'NONE'
]);

const kind =
  command?.kind ?? null;

const action =
  command?.action ?? 'NONE';


if (
  kind
  && !allowedKinds.has(kind)
) {
  errors.push('INVALID_KIND');
}


if (
  action
  && !allowedActions.has(action)
) {
  errors.push('INVALID_ACTION');
}


// ======================================================
// DIRECT RESPONSE
// ======================================================

let directResponse =
  typeof command?.direct_response === 'string'
    ? command.direct_response.trim()
    : null;

if (directResponse === '') {
  directResponse = null;
}


// BUSINESS_ACTION nunca pode responder antes do CORE.
if (
  kind === 'BUSINESS_ACTION'
  && directResponse !== null
) {
  warnings.push(
    'DIRECT_RESPONSE_IGNORED_FOR_BUSINESS_ACTION'
  );

  directResponse = null;
}


// Conversa / informação faltante / handoff
// precisam possuir mensagem pronta.
if (
  (
    kind === 'CONVERSATION'
    || kind === 'NEED_INFORMATION'
    || kind === 'HUMAN_HANDOFF'
  )
  && !directResponse
) {
  errors.push('DIRECT_RESPONSE_REQUIRED');
}


// Tudo que não for BUSINESS_ACTION
// deve usar action NONE.
if (
  kind !== 'BUSINESS_ACTION'
  && action !== 'NONE'
) {
  errors.push(
    'NON_BUSINESS_KIND_MUST_USE_NONE'
  );
}


// BUSINESS_ACTION deve ter ação real.
if (
  kind === 'BUSINESS_ACTION'
  && action === 'NONE'
) {
  errors.push(
    'BUSINESS_ACTION_REQUIRES_ACTION'
  );
}


// ======================================================
// CATÁLOGO REAL
// ======================================================

const services =
  Array.isArray(context.services)
    ? context.services
    : [];

const professionals =
  Array.isArray(context.professionals)
    ? context.professionals
    : [];

const serviceId =
  command?.arguments?.service_id
  ?? null;

const professionalId =
  command?.arguments?.professional_id
  ?? null;


// ======================================================
// VALIDAR SERVICE_ID
// ======================================================

let validatedService = null;

if (serviceId) {

  validatedService =
    services.find(
      service =>
        service.service_id === serviceId
    )
    ?? null;

  if (!validatedService) {
    errors.push('UNKNOWN_SERVICE_ID');
  }
}


// ======================================================
// VALIDAR PROFESSIONAL_ID
// ======================================================

let validatedProfessional = null;

if (professionalId) {

  validatedProfessional =
    professionals.find(
      professional =>
        professional.professional_id
        === professionalId
    )
    ?? null;

  if (!validatedProfessional) {
    errors.push('UNKNOWN_PROFESSIONAL_ID');
  }
}


// ======================================================
// SERVIÇO × PROFISSIONAL
// ======================================================

if (
  validatedService
  && validatedProfessional
) {

  const professionalAllowed =
    Array.isArray(
      validatedService.professionals
    )
    && validatedService.professionals.some(
      professional =>
        professional.professional_id
        === validatedProfessional.professional_id
    );

  if (!professionalAllowed) {
    errors.push(
      'PROFESSIONAL_DOES_NOT_PERFORM_SERVICE'
    );
  }
}


// ======================================================
// DATA
// ======================================================

const requestedDate =
  command?.arguments?.date
  ?? null;

const localDate =
  context.clock?.local_date
  ?? null;


if (
  requestedDate
  && !/^\d{4}-\d{2}-\d{2}$/.test(
    requestedDate
  )
) {
  errors.push('INVALID_DATE_FORMAT');
}


if (
  action === 'SEARCH_AVAILABILITY'
  && requestedDate
  && localDate
  && requestedDate < localDate
) {
  errors.push('DATE_IN_PAST');
}


// ======================================================
// SEARCH_AVAILABILITY
// ======================================================

if (
  kind === 'BUSINESS_ACTION'
  && action === 'SEARCH_AVAILABILITY'
) {

  if (!serviceId) {
    errors.push(
      'SEARCH_REQUIRES_SERVICE'
    );
  }

  if (!requestedDate) {
    errors.push(
      'SEARCH_REQUIRES_DATE'
    );
  }
}


// ======================================================
// SELECT_SLOT
// ======================================================

if (
  kind === 'BUSINESS_ACTION'
  && action === 'SELECT_SLOT'
) {

  const offer =
    context.active_offer ?? null;

  const optionNumber =
    command?.arguments?.option_number
    ?? null;


  if (!offer) {
    errors.push(
      'NO_ACTIVE_SLOT_OFFER'
    );
  }


  if (!optionNumber) {
    errors.push(
      'SELECT_SLOT_REQUIRES_OPTION'
    );
  }


  if (
    offer
    && optionNumber
  ) {

    const optionExists =
      Array.isArray(offer.options)
      && offer.options.some(
        option =>
          option.option_number
          === optionNumber
      );

    if (!optionExists) {
      errors.push(
        'UNKNOWN_SLOT_OPTION'
      );
    }
  }
}


// ======================================================
// REBOOK_APPOINTMENT
// ======================================================

if (
  kind === 'BUSINESS_ACTION'
  && action === 'REBOOK_APPOINTMENT'
) {

  const appointmentId =
    command?.arguments?.appointment_id
    ?? null;


  if (!appointmentId) {

    errors.push(
      'REBOOK_REQUIRES_APPOINTMENT'
    );

  } else if (
    typeof appointmentId !== 'string'
    || !uuidRegex.test(appointmentId)
  ) {

    errors.push(
      'INVALID_APPOINTMENT_ID'
    );
  }
}


// ======================================================
// CANCEL_APPOINTMENT
//
// Aqui validamos apenas formato.
// Autorização, dono do appointment e regras de horário
// continuam sendo responsabilidade do CORE.
// ======================================================

if (
  kind === 'BUSINESS_ACTION'
  && action === 'CANCEL_APPOINTMENT'
) {

  const appointmentId =
    command?.arguments?.appointment_id
    ?? null;


  if (!appointmentId) {

    errors.push(
      'CANCEL_REQUIRES_APPOINTMENT'
    );

  } else if (
    typeof appointmentId !== 'string'
    || !uuidRegex.test(appointmentId)
  ) {

    errors.push(
      'INVALID_APPOINTMENT_ID'
    );
  }
}


// ======================================================
// RESCHEDULE_APPOINTMENT
//
// Ainda não executamos o motor completo aqui,
// mas já protegemos appointment_id.
// ======================================================

if (
  kind === 'BUSINESS_ACTION'
  && action === 'RESCHEDULE_APPOINTMENT'
) {

  const appointmentId =
    command?.arguments?.appointment_id
    ?? null;


  if (!appointmentId) {

    errors.push(
      'RESCHEDULE_REQUIRES_APPOINTMENT'
    );

  } else if (
    typeof appointmentId !== 'string'
    || !uuidRegex.test(appointmentId)
  ) {

    errors.push(
      'INVALID_APPOINTMENT_ID'
    );
  }
}


// ======================================================
// GET_APPOINTMENT
// ======================================================

if (
  kind === 'BUSINESS_ACTION'
  && action === 'GET_APPOINTMENT'
) {

  const appointmentId =
    command?.arguments?.appointment_id
    ?? null;


  if (
    appointmentId
    && (
      typeof appointmentId !== 'string'
      || !uuidRegex.test(appointmentId)
    )
  ) {

    errors.push(
      'INVALID_APPOINTMENT_ID'
    );
  }
}


// ======================================================
// MISSING INFORMATION
// ======================================================

const missingInformation =
  Array.isArray(
    command?.missing_information
  )
    ? command.missing_information
    : [];


if (
  kind === 'NEED_INFORMATION'
  && missingInformation.length === 0
) {
  warnings.push(
    'NEED_INFORMATION_WITHOUT_MISSING_FIELDS'
  );
}


// ======================================================
// CONFIANÇA
// ======================================================

const confidence =
  Number(
    command?.confidence ?? 0
  );

const minimumConfidence =
  Number(
    context.ai_settings
      ?.minimum_intent_confidence
    ?? 0.7
  );


if (
  kind === 'BUSINESS_ACTION'
  && confidence < minimumConfidence
) {
  errors.push(
    'LOW_AI_CONFIDENCE_FOR_EXECUTION'
  );
}


// ======================================================
// DEFINIR ROTA ESTRUTURAL
// ======================================================

let route = 'INVALID';

if (errors.length === 0) {

  if (kind === 'BUSINESS_ACTION') {

    route = 'CORE';

  } else if (
    kind === 'CONVERSATION'
    || kind === 'NEED_INFORMATION'
  ) {

    route = 'DIRECT_RESPONSE';

  } else if (
    kind === 'HUMAN_HANDOFF'
  ) {

    route = 'HUMAN_HANDOFF';

  }
}


// ======================================================
// OUTPUT CANÔNICO V3
//
// action_args porque "arguments" dá problema
// em expressões do sandbox do n8n.
// ======================================================

return {
  json: {

    validated_command: {

      valid:
        errors.length === 0,

      executable:
        errors.length === 0
        && route === 'CORE',

      route,

      kind,

      intent:
        command?.intent
        ?? null,

      action,

      action_args: {
        ...(command?.arguments ?? {}),

        service_id:
          validatedService?.service_id
          ?? serviceId
          ?? null,

        professional_id:
          validatedProfessional?.professional_id
          ?? professionalId
          ?? null
      },

      service:
        validatedService,

      professional:
        validatedProfessional,

      missing_information:
        missingInformation,

      customer_meaning:
        command?.customer_meaning
        ?? '',

      direct_response:
        directResponse,

      confidence,

      minimum_confidence:
        minimumConfidence,

      errors,

      warnings
    },

    context
  }
};

const execution = $json.execution ?? {};
const validated = $('05 - VALIDAR COMANDO IA').first().json.validated_command ?? {};
const context = $('05 - VALIDAR COMANDO IA').first().json.context ?? {};
const originalInput = $('01 - NORMALIZAR ENTRADA').first().json;

const systemInstruction = "
Você é o RESPONSE ENGINE da ML Automações.

OBJETIVO
Transformar fatos já confirmados pelo Business Core em uma mensagem curta, natural,
contextual e adequada ao WhatsApp. O Core é a única fonte de verdade operacional.

REGRA PRINCIPAL
Você pode mudar a forma de comunicar, mas nunca pode mudar os fatos.

NUNCA INVENTE OU ALTERE
- disponibilidade;
- horários, datas ou timezone;
- preços, moeda ou duração;
- serviço ou profissional;
- appointment_id, status ou resultado;
- motivo de cancelamento;
- política, regra ou permissão;
- existência de vaga, confirmação, cancelamento, remarcação ou rebooking;
- resultado de Calendar, WhatsApp ou qualquer integração.

Se core_execution.ok for false, não diga que a ação deu certo.
Se houver HOLD sem confirmação, não diga que está confirmado.
Se houver SLOT_OFFER, não liste opções no texto quando a interface interativa as exibirá.

FONTES
Use exclusivamente:
- core_execution
- interpreted_command
- original_message
- recent_messages
- business
- brand
- customer
- clock

SLOT_OFFER
Quando result_type ou resultado representar oferta de horários:
- escreva apenas uma introdução humana;
- não enumere horários;
- convide o cliente a escolher na lista/botões;
- mencione serviço/profissional/preço somente se estiverem nos fatos e ajudarem.

CONFIRMAÇÃO
Quando o Core confirmar um appointment, comunique os dados disponíveis de forma enxuta.
Não transforme ausência de dado em suposição.

CANCELAMENTO
Se confirmado, informe que o appointment foi cancelado. Motivo público só pode ser repetido
se estiver explicitamente presente. Se o Core indicar possibilidade de rebooking, pode convidar
o cliente a procurar outro horário.

REMARCAÇÃO
Só diga que foi remarcado quando o Core retornar sucesso de rescheduling. Se o Core apenas
ofereceu horários, trate como oferta e peça escolha.

REBOOKING
Appointment cancelado + nova busca não significa novo appointment confirmado. Diferencie
oferta de horários de confirmação.

GET_APPOINTMENT
Apresente apenas os dados reais retornados.

WAITLIST
Só diga que entrou na lista se o Core confirmar. Não prometa atendimento.

ERROS
Não exponha stack trace, SQL, n8n, nomes de funções, IDs internos desnecessários ou códigos
técnicos. Explique em linguagem humana. Quando houver um próximo passo seguro e evidente,
sugira-o sem inventar disponibilidade.

NATURALIDADE
Continue a conversa em vez de reiniciá-la. Evite fórmulas repetitivas. Respeite brand:
brand_personality, default_treatment, minimum_formality, maximum_informality, allow_slang,
emoji_max_per_message, response_guidelines, greeting_text e farewell_text.
Use o idioma predominante do cliente. Não copie erros ortográficos.

TAMANHO
Prefira mensagens curtas ou médias, com quebras de linha somente quando melhorarem a leitura.

SAÍDA
Retorne SOMENTE o objeto do JSON Schema.
O campo text contém exclusivamente a mensagem destinada ao cliente.
";

return {
  json: {
    response_request: {
      system_instruction: systemInstruction,
      input: {
        original_message: originalInput.message?.normalized_text ?? originalInput.message?.text ?? null,
        interpreted_command: validated,
        core_execution: execution,
        recent_messages: context.recent_messages ?? [],
        business: {
          name: context.business?.name ?? null,
          timezone: context.business?.timezone ?? null,
          locale: context.business?.locale ?? 'pt-BR'
        },
        brand: context.brand ?? {},
        customer: {
          name: context.customer?.name ?? null,
          communication_profile: context.customer?.communication_profile ?? {},
          preferences: context.customer?.preferences ?? {}
        },
        clock: context.clock ?? {}
      }
    }
  }
};

const execution = $('06 - EXECUTAR AÇÃO CORE').first().json.execution ?? {};
const context = $('05 - VALIDAR COMANDO IA').first().json.context ?? {};
const result = execution.result ?? {};
const rt = String(execution.result_type ?? result.result_type ?? '').toUpperCase();
const code = String(execution.code ?? result.code ?? '').toUpperCase();

const fmtDate = value => value ? String(value) : null;
const fmtTime = value => value ? String(value).slice(0,5) : null;

let text = null;
let responseType = 'GENERAL';

const slots = Array.isArray(result.slots) ? result.slots : [];
if ((rt.includes('SLOT_OFFER') || code.includes('SLOT_OFFER')) && slots.length > 0) {
  text = 'Encontrei algumas opções de horário. Escolhe a que ficar melhor pra você 👇';
  responseType = 'SLOT_OPTIONS';
} else if (execution.ok === true && (rt.includes('RESCHEDULE') || code === 'APPOINTMENT_RESCHEDULED')) {
  const a = result.appointment ?? result.replacement_appointment ?? execution.appointment ?? {};
  const d = a.local_date ?? result.local_date ?? null;
  const t = a.local_start ?? result.local_start ?? null;
  text = `Pronto, seu horário foi remarcado${d ? ` para ${fmtDate(d)}` : ''}${t ? ` às ${fmtTime(t)}` : ''}.`;
  responseType = 'CONFIRMATION';
} else if (execution.ok === true && (rt.includes('CANCELLATION') || code === 'APPOINTMENT_CANCELLED')) {
  text = 'Certo, seu agendamento foi cancelado.';
  responseType = 'CONFIRMATION';
} else if (execution.ok === true && (rt.includes('CONFIRM') || code.includes('CONFIRMED'))) {
  const a = result.appointment ?? execution.appointment ?? {};
  const d = a.local_date ?? result.local_date ?? null;
  const t = a.local_start ?? result.local_start ?? null;
  text = `Fechado, seu horário ficou confirmado${d ? ` para ${fmtDate(d)}` : ''}${t ? ` às ${fmtTime(t)}` : ''}.`;
  responseType = 'CONFIRMATION';
} else if (execution.ok === true && rt.includes('APPOINTMENT')) {
  const a = result.appointment ?? result ?? {};
  const d = a.local_date ?? null;
  const t = a.local_start ?? null;
  text = (d || t)
    ? `Seu agendamento${d ? ` é em ${fmtDate(d)}` : ''}${t ? ` às ${fmtTime(t)}` : ''}.`
    : 'Encontrei seu agendamento.';
  responseType = 'INFORMATION';
} else if (execution.ok === true && (rt.includes('WAITLIST') || code.includes('WAITLIST'))) {
  text = 'Certo, registrei sua solicitação na lista de espera.';
  responseType = 'CONFIRMATION';
} else if (execution.ok === true) {
  text = 'Certo, concluí essa solicitação.';
  responseType = 'CONFIRMATION';
} else {
  text = 'Não consegui concluir isso agora. Tenta novamente ou me diga de outra forma o que você precisa.';
  responseType = 'ERROR';
}

return {
  json: {
    fallback_response: {
      text,
      response_type: responseType,
      should_send: true,
      source: 'DETERMINISTIC_FALLBACK'
    }
  }
};

const validated = $('05 - VALIDAR COMANDO IA').first().json.validated_command ?? {};
let coreExecution = {};
try {
  coreExecution = $('06 - EXECUTAR AÇÃO CORE').first().json.execution ?? {};
} catch {
  coreExecution = {};
}

let text = null;
let responseType = 'GENERAL';
let shouldSend = true;
let source = null;

if (validated.route !== 'CORE') {
  text = typeof validated.direct_response === 'string' ? validated.direct_response.trim() : null;
  if (validated.kind === 'NEED_INFORMATION') responseType = 'QUESTION';
  else if (validated.kind === 'HUMAN_HANDOFF') responseType = 'HANDOFF';
  else if (validated.route === 'INVALID') responseType = 'ERROR';
  else responseType = 'INFORMATION';
  source = validated.route === 'INVALID' ? 'VALIDATION_FALLBACK' : 'ORCHESTRATOR_DIRECT';
}

if (!text && $json.fallback_response) {
  text = String($json.fallback_response.text ?? '').trim();
  responseType = $json.fallback_response.response_type ?? 'GENERAL';
  shouldSend = $json.fallback_response.should_send !== false;
  source = $json.fallback_response.source ?? 'DETERMINISTIC_FALLBACK';
}

if (!text) {
  let response = $json.output?.[0]?.content?.find(c => c.type === 'output_text')?.text ?? null;
  if (typeof response === 'string') {
    try { response = JSON.parse(response); } catch { /* keep string below */ }
  }
  if (response && typeof response === 'object') {
    text = String(response.text ?? '').trim();
    responseType = response.response_type ?? 'GENERAL';
    shouldSend = response.should_send !== false;
  } else if (typeof response === 'string') {
    text = response.trim();
  }
  source = 'RESPONSE_ENGINE';
}

if (!text) {
  text = validated.route === 'INVALID'
    ? 'Não consegui entender essa solicitação com segurança. Pode me dizer de outra forma o que você precisa?'
    : 'Tive um problema para preparar a resposta. Pode tentar novamente?';
  responseType = 'ERROR';
  shouldSend = true;
  source = 'FINAL_SAFETY_FALLBACK';
}

return {
  json: {
    final_response: {
      valid: true,
      should_send: shouldSend,
      text: text.trim(),
      response_type: responseType,
      source,
      route: validated.route ?? null,
      kind: validated.kind ?? null,
      intent: validated.intent ?? null
    },
    core_execution: coreExecution
  }
};

const f = $json.finalization ?? {};
if (f.ok !== true) {
  throw new Error(`FINALIZE_ASSISTANT_TURN_FAILED:${f.code ?? 'UNKNOWN'}`);
}
return { json: { ok: true, finalization: f } };
